#include <stdio.h>

int bowl[8] = {1, 2, 3, 4, 5, 6, 7, 8};

/* 挨着看：从第一只开始一只只比过去，答「一共看了几下」 */
int seen(int n, int want) {
    int tries = 0;
    for (int i = 0; i < n; i++) {
        if (bowl[i] == want) {
            tries = tries + 1;
            return tries;
        }
    }
    return tries;
}

int main(void) {
    printf("%d\n", seen({n}, {n}));
    return 0;
}

referenceFixTemplate:
#include <stdio.h>

int bowl[8] = {1, 2, 3, 4, 5, 6, 7, 8};

/* 挨着看：从第一只开始一只只比过去，答「一共看了几下」 */
int seen(int n, int want) {
    int tries = 0;
    for (int i = 0; i < n; i++) {
        tries = tries + 1;
        if (bowl[i] == want) {
            return tries;
        }
    }
    return tries;
}

int main(void) {
    printf("%d\n", seen({n}, {n}));
    return 0;
}

explanationTemplate:
毛病在**记账的位置**喵：`tries` 加一的动作被关在 `if` **里面**，只有「对上了」的那一只才记得上账。可**看过的每一只碗都出了力** —— 前面那些没对上的，本喵照样一只一只看过去了，这些圈数不能凭空消失。

```text
for (int i = 0; i < n; i++) {
    tries = tries + 1;      /* 先记账，再看这一只 */
    if (bowl[i] == want) {
        return tries;
    }
}
```

**每比一次就记一笔，中了的这一下也算**，所以看最末尾那一只要记满一整排。

这就是课文第五节说的**最坏情况**：同一个本子、同一段代码，要找的摆在头一只就只记 1 下，摆在最末尾就得记满 {n} 下。本喵报大 O 的时候按**最满的那一头**报，就是不想被运气骗了。
